BEGIN;
CREATE TEMP TABLE gm_tools_results(test text,result text) ON COMMIT DROP;
GRANT SELECT,INSERT ON gm_tools_results TO authenticated,anon;
DO $test$
DECLARE gm uuid:='11111111-1111-4111-8111-111111111111'; player uuid:='22222222-2222-4222-8222-222222222222';
 outsider uuid:='33333333-3333-4333-8333-333333333333'; room uuid:=gen_random_uuid(); otherroom uuid:=gen_random_uuid();
 sheet uuid:=gen_random_uuid(); peer uuid:=gen_random_uuid(); foreignsheet uuid:=gen_random_uuid(); instance uuid:=gen_random_uuid();
 own uuid:=gen_random_uuid(); ally uuid:=gen_random_uuid(); monster uuid:=gen_random_uuid(); hidden uuid:=gen_random_uuid();
 m1 uuid; m2 uuid; delivery uuid:=gen_random_uuid(); n integer; denied boolean; res jsonb; note jsonb; rev bigint;
BEGIN
 INSERT INTO public.mesas(id,nome,mestre_id,codigo_convite) VALUES(room,'GM tools temporary',gm,upper(substr(md5(random()::text),1,6))),
 (otherroom,'GM tools external',outsider,upper(substr(md5(random()::text),1,6)));
 INSERT INTO public.membros_mesa(mesa_id,usuario_id,cargo) VALUES(room,gm,'mestre'),(room,player,'jogador');
 SELECT mapa_ativo_jogadores_id INTO m1 FROM public.mesas WHERE id=room;
 INSERT INTO public.fichas(id,usuario_id,mesa_id,nome_personagem,dados) VALUES
 (sheet,player,room,'Player','{"config6B":{"d6":6},"usedChambers":[0,1],"damagedChambers":[],"rem-total":8,"rem-atual":5}'),
 (peer,gm,room,'Ally','{"config-6b":"4d6","damagedChambers":[1]}'),(foreignsheet,outsider,otherroom,'External','{}');
 UPDATE public.mesas SET cena_ativa=jsonb_build_array(jsonb_build_object('instanceId',instance,'name','Monster','data','{"config-6b":"8d6","damagedChambers":[0,1],"rem-total":12,"rem-atual":9}'::jsonb)) WHERE id=room;
 INSERT INTO public.mesa_tokens(id,mesa_id,mapa_id,owner_type,owner_ref,owner_user_id,display_name,visible_to_players) VALUES
 (own,room,m1,'player',sheet,player,'Own',false),(ally,room,m1,'player',peer,gm,'Ally',true),
 (monster,room,m1,'creature',instance,NULL,'Monster',true),(hidden,room,m1,'player',gen_random_uuid(),gm,'Hidden ally',false);
 IF (SELECT six_b_total FROM public.mesa_token_status WHERE token_id=monster)<>8 OR (SELECT danos_bloqueados FROM public.mesa_token_status WHERE token_id=monster)<>2 THEN RAISE EXCEPTION 'source summary'; END IF;
 INSERT INTO gm_tools_results VALUES('Status inicial deriva instância da criatura e respeita 8 câmaras','PASS');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',gm,'role','authenticated')::text,true); EXECUTE 'SET LOCAL ROLE authenticated';
 res:=public.gerenciar_mapas(room,'adicionar'); m2:=(res->>'mapa_id')::uuid;
 INSERT INTO public.mesa_tokens(mesa_id,mapa_id,owner_type,owner_ref,owner_user_id,display_name,visible_to_players) VALUES(room,m2,'player',sheet,player,'Own preparation',true);
 IF (SELECT count(*) FROM public.mesa_token_status WHERE mesa_id=room)<>5 THEN RAISE EXCEPTION 'GM all statuses'; END IF;
 INSERT INTO gm_tools_results VALUES('Mestre lê status visíveis, ocultos e de outros mapas','PASS');
 note:=jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'tipo','pasta','nome','Capítulo','itens',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'tipo','arquivo','nome','Pista','conteudo','Segredo'))));
 UPDATE public.mesas SET notas_mestre=note WHERE id=room AND notas_mestre_versao=1;
 SELECT notas_mestre_versao INTO rev FROM public.mesas WHERE id=room;
 IF rev<>2 OR (SELECT notas_mestre FROM public.mesas WHERE id=room)<>note THEN RAISE EXCEPTION 'notes persist'; END IF;
 INSERT INTO gm_tools_results VALUES('Mestre salva árvore e versão avança','PASS');
 UPDATE public.mesas SET notas_mestre='[]' WHERE id=room AND notas_mestre_versao=1; GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>0 THEN RAISE EXCEPTION 'stale notes write'; END IF;
 INSERT INTO gm_tools_results VALUES('Edição de notas com versão antiga não sobrescreve','PASS');
 denied:=false; BEGIN UPDATE public.mesas SET notas_mestre='{}' WHERE id=room; EXCEPTION WHEN invalid_parameter_value THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'invalid notes'; END IF;
 INSERT INTO gm_tools_results VALUES('Schema inválido de notas rejeitado','PASS');
 res:=public.enviar_item_para_jogador(room,sheet,'{"nome":"Colt","group":"armas","dano":"d6"}',2,delivery);
 PERFORM public.enviar_item_para_jogador(room,sheet,'{"nome":"Colt","group":"armas","dano":"d6"}',2,delivery);
 IF (SELECT count(*) FROM public.itens_entregues_pendentes WHERE id=delivery)<>1 OR (SELECT dados ? 'inventoryItems' FROM public.fichas WHERE id=sheet) THEN RAISE EXCEPTION 'inbox mutated sheet or duplicated'; END IF;
 INSERT INTO gm_tools_results VALUES('Envio do Mestre cria fila idempotente sem escrever ficha','PASS');
 denied:=false; BEGIN PERFORM public.enviar_item_para_jogador(room,foreignsheet,'{"nome":"Item"}',1); EXCEPTION WHEN invalid_parameter_value THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'external recipient'; END IF;
 INSERT INTO gm_tools_results VALUES('Envio para ficha de outra mesa rejeitado','PASS');
 denied:=false; BEGIN PERFORM public.enviar_item_para_jogador(room,sheet,'{"nome":"Item"}',0); EXCEPTION WHEN invalid_parameter_value THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'invalid quantity'; END IF;
 INSERT INTO gm_tools_results VALUES('Quantidade inválida rejeitada','PASS');
 UPDATE public.fichas SET dados='{"inventario":"Corda antiga x1"}' WHERE id=peer;
 IF (SELECT dados ? 'inventoryItems' FROM public.fichas WHERE id=peer) THEN RAISE EXCEPTION 'legacy inventory shadowed'; END IF;
 INSERT INTO gm_tools_results VALUES('Ficha sem entregas mantém inventário legado intacto','PASS');
 EXECUTE 'RESET ROLE'; PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',player,'role','authenticated')::text,true); EXECUTE 'SET LOCAL ROLE authenticated';
 IF (SELECT count(*) FROM public.mesa_token_status WHERE mesa_id=room)<>2 OR EXISTS(SELECT 1 FROM public.mesa_token_status WHERE token_id IN(monster,hidden)) THEN RAISE EXCEPTION 'status visibility'; END IF;
 INSERT INTO gm_tools_results VALUES('Jogador recebe apenas próprio status e aliado revelado no mapa da flâmula','PASS');
 IF EXISTS(SELECT 1 FROM public.mesas WHERE id=room) THEN RAISE EXCEPTION 'private notes'; END IF;
 UPDATE public.mesas SET notas_mestre='[]' WHERE id=room; GET DIAGNOSTICS n=ROW_COUNT; IF n<>0 THEN RAISE EXCEPTION 'write notes'; END IF;
 INSERT INTO gm_tools_results VALUES('Jogador não lê nem altera notas via tabela privada','PASS');
 denied:=false; BEGIN PERFORM public.enviar_item_para_jogador(room,sheet,'{"nome":"Item"}',1); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'player send'; END IF;
 INSERT INTO gm_tools_results VALUES('Jogador não envia itens como Mestre','PASS');
 IF (SELECT count(*) FROM public.itens_entregues_pendentes WHERE id=delivery)<>1 THEN RAISE EXCEPTION 'recipient inbox'; END IF;
 denied:=false; BEGIN UPDATE public.itens_entregues_pendentes SET quantidade=999,entregue=true WHERE id=delivery; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'mutated delivery'; END IF;
 INSERT INTO gm_tools_results VALUES('Destinatário lê fila, mas não falsifica quantidade ou confirmação direta','PASS');
 denied:=false; BEGIN PERFORM public.confirmar_entrega_item(delivery); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'early ack'; END IF;
 INSERT INTO gm_tools_results VALUES('Confirmação antes de salvar recibo é bloqueada','PASS');
 UPDATE public.fichas SET dados=dados||jsonb_build_object('receivedDeliveryIds',jsonb_build_array(delivery),'inventoryItems',jsonb_build_array(jsonb_build_object('id',delivery,'name','Colt','qty',2))) WHERE id=sheet;
 PERFORM public.confirmar_entrega_item(delivery); PERFORM public.confirmar_entrega_item(delivery);
 IF NOT (SELECT entregue FROM public.itens_entregues_pendentes WHERE id=delivery) THEN RAISE EXCEPTION 'ack'; END IF;
 INSERT INTO gm_tools_results VALUES('Jogador persiste item/recibo e confirma entrega sem duplicar','PASS');
 UPDATE public.fichas SET dados='{"inventoryItems":[],"usedChambers":[0,1,2],"damagedChambers":[],"rem-total":8,"rem-atual":4}' WHERE id=sheet;
 IF jsonb_array_length((SELECT dados->'inventoryItems' FROM public.fichas WHERE id=sheet))<>1 THEN RAISE EXCEPTION 'stale save lost item'; END IF;
 INSERT INTO gm_tools_results VALUES('Salvamento concorrente antigo preserva item recebido','PASS');
 IF (SELECT danos_bloqueados FROM public.mesa_token_status WHERE token_id=own)<>0 THEN RAISE EXCEPTION 'shots became damage'; END IF;
 INSERT INTO gm_tools_results VALUES('Consumir dados para tiros não reduz integridade','PASS');
 UPDATE public.fichas SET dados=dados||'{"damagedChambers":[1,3],"rem-atual":2}'::jsonb WHERE id=sheet;
 IF (SELECT danos_bloqueados FROM public.mesa_token_status WHERE token_id=own)<>2 OR (SELECT rem_current FROM public.mesa_token_status WHERE token_id=own)<>2 THEN RAISE EXCEPTION 'damage/rem sync'; END IF;
 INSERT INTO gm_tools_results VALUES('Dano real e REM sincronizam automaticamente após salvar ficha','PASS');
 UPDATE public.fichas SET dados=jsonb_set(dados,'{inventoryItems}','[]') WHERE id=sheet;
 IF jsonb_array_length((SELECT dados->'inventoryItems' FROM public.fichas WHERE id=sheet))<>0 THEN RAISE EXCEPTION 'cannot remove consumed item'; END IF;
 INSERT INTO gm_tools_results VALUES('Sessão que conhece recibo pode consumir/remover o item normalmente','PASS');
 denied:=false; BEGIN PERFORM public.sincronizar_token_status(monster,8,8,0,12); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'player monster status write'; END IF;
 INSERT INTO gm_tools_results VALUES('Jogador não altera status de criatura alheia','PASS');
 denied:=false; BEGIN PERFORM public.sincronizar_token_status(gen_random_uuid(),6,0,NULL,NULL); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'missing token auth null bypass'; END IF;
 INSERT INTO gm_tools_results VALUES('RPC de status rejeita token inexistente','PASS');
 PERFORM public.sincronizar_token_status(own,6,2,2,8);
 INSERT INTO gm_tools_results VALUES('Proprietário sincroniza próprio token autorizado','PASS');
 EXECUTE 'RESET ROLE'; PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true); EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM public.itens_entregues_pendentes WHERE mesa_id=room) OR EXISTS(SELECT 1 FROM public.mesa_token_status WHERE mesa_id=room) THEN RAISE EXCEPTION 'outsider leak'; END IF;
 INSERT INTO gm_tools_results VALUES('Não membro não recebe fila nem status','PASS');
 EXECUTE 'RESET ROLE'; PERFORM set_config('request.jwt.claims','{"role":"anon"}',true); EXECUTE 'SET LOCAL ROLE anon';
 denied:=false; BEGIN PERFORM public.enviar_item_para_jogador(room,sheet,'{"nome":"Item"}',1); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'anon RPC'; END IF;
 INSERT INTO gm_tools_results VALUES('Anon não executa RPC de entrega','PASS');
 denied:=false; BEGIN PERFORM public.sincronizar_token_status(own,6,2,NULL,NULL); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'anon status RPC'; END IF;
 INSERT INTO gm_tools_results VALUES('Anon não executa RPC de status','PASS');
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='mesa_token_status') OR
 NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='itens_entregues_pendentes') THEN RAISE EXCEPTION 'publication'; END IF;
 INSERT INTO gm_tools_results VALUES('As duas tabelas estão publicadas no Realtime','PASS');
END $test$;
SELECT * FROM gm_tools_results;
ROLLBACK;
